import test from "node:test";
import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
import {createHash} from "node:crypto";
import {Keypair,PublicKey} from "@solana/web3.js";
import {createTreasuryClient,decodeTreasury,encodePolicy,LOCALNET_PROGRAM_ID,treasuryConfigFromEnv,treasuryErrorName,TREASURY_ERRORS} from "./chain-client.mjs";

// IDL generated by `anchor build` from PARRALAX-AIHFTFUND PR #17 (solana/, layout v2).
const IDL=JSON.parse(readFileSync(new URL("./idl/parralax_agent_treasury.v2.json",import.meta.url),"utf8"));
const PROGRAM=IDL.address;
const pk=()=>Keypair.generate().publicKey;
const owner=pk(),agent=pk(),beneficiary=pk(),mint=pk(),guardian=pk(),token=pk(),newAgent=pk();
const EXPIRES=4102444800; // 2100-01-01
const client=()=>createTreasuryClient({programId:PROGRAM,verifiedProgramId:PROGRAM,network:"localnet"});

function idlPda(ix,name,ctx){
 const acc=IDL.instructions.find(i=>i.name===ix).accounts.find(a=>a.name===name);
 const seeds=acc.pda.seeds.map(s=>{
  if(s.kind==="const")return Buffer.from(s.value);
  if(s.kind==="account")return ctx[s.path].toBuffer();
  if(s.kind==="arg"){const b=Buffer.alloc(8);b.writeBigUInt64LE(BigInt(ctx[s.path]));return b;}
  throw Error("seed kind "+s.kind);
 });
 const programId=acc.pda.program?new PublicKey(Buffer.from(acc.pda.program.value)):new PublicKey(PROGRAM);
 return PublicKey.findProgramAddressSync(seeds,programId)[0];
}
function build(name){
 const c=client(),base={owner,mint,seedId:7n};
 switch(name){
  case "initialize":return c.initialize({...base,agent,beneficiary,perTxMinor:100,dailyMinor:200,lifetimeMinor:300,expiresAt:EXPIRES,guardian}).instruction;
  case "deposit":return c.deposit({...base,ownerToken:token,amountMinor:5});
  case "spend":return c.spend({...base,agent,beneficiaryToken:token,amountMinor:5,nonce:3});
  case "withdraw":return c.withdraw({...base,ownerToken:token,amountMinor:5});
  case "update_policy":return c.updatePolicy({...base,perTxMinor:1,dailyMinor:2,lifetimeMinor:3,expiresAt:EXPIRES});
  case "rotate_agent":return c.rotateAgent({...base,newAgent});
  case "set_guardian":return c.setGuardian({...base,guardian});
  case "pause":return c.pause({...base,authority:guardian});
  case "unpause":return c.unpause(base);
  case "revoke":return c.revoke({...base,authority:guardian});
  case "close":return c.close({...base,ownerToken:token});
 }
 throw Error("no builder for "+name);
}

test("every IDL instruction has a builder with matching discriminator and account metas",()=>{
 const c=client(),{treasury,vault}=c.derive(owner,mint,7n);
 assert.equal(treasury.equals(idlPda("initialize","treasury",{owner,mint,seed_id:7n})),true);
 assert.equal(vault.equals(idlPda("initialize","vault",{treasury,mint})),true);
 for(const ix of IDL.instructions){
  const built=build(ix.name);
  assert.deepEqual([...built.data.subarray(0,8)],ix.discriminator,ix.name+" discriminator");
  assert.equal(built.keys.length,ix.accounts.length,ix.name+" account count");
  ix.accounts.forEach((a,i)=>{
   const k=built.keys[i];
   assert.equal(k.isSigner,Boolean(a.signer),`${ix.name}.${a.name} signer`);
   assert.equal(k.isWritable,Boolean(a.writable),`${ix.name}.${a.name} writable`);
   if(a.address)assert.equal(k.pubkey.toBase58(),a.address,`${ix.name}.${a.name} address`);
   if(a.name==="treasury")assert.equal(k.pubkey.equals(treasury),true,`${ix.name} treasury PDA`);
   if(a.name==="vault")assert.equal(k.pubkey.equals(vault),true,`${ix.name} vault ATA`);
  });
 }
});

test("PDA is keyed by owner, mint and seed_id only (agent can rotate, several per owner+mint)",()=>{
 const c=client();
 assert.equal(c.derive(owner,mint,0n).treasury.equals(c.derive(owner,mint,0n).treasury),true);
 assert.equal(c.derive(owner,mint,0n).treasury.equals(c.derive(owner,mint,1n).treasury),false);
 assert.equal(c.derive(owner,mint,0n).treasury.equals(c.derive(owner,pk(),0n).treasury),false);
 const a=c.spend({owner,agent,mint,beneficiaryToken:token,amountMinor:1,nonce:0});
 const b=c.spend({owner,agent:newAgent,mint,beneficiaryToken:token,amountMinor:1,nonce:0});
 assert.equal(a.keys[1].pubkey.equals(b.keys[1].pubkey),true);
});

test("initialize encodes seed_id, PolicyParams and Option<guardian> little-endian",()=>{
 const c=client();
 const withG=c.initialize({owner,agent,beneficiary,mint,seedId:9n,perTxMinor:"100",dailyMinor:"200",lifetimeMinor:"300",expiresAt:EXPIRES,guardian}).instruction.data;
 assert.equal(withG.length,8+8+32+1+32);
 assert.equal(withG.readBigUInt64LE(8),9n);
 assert.equal(withG.readBigUInt64LE(16),100n);
 assert.equal(withG.readBigUInt64LE(24),200n);
 assert.equal(withG.readBigUInt64LE(32),300n);
 assert.equal(withG.readBigInt64LE(40),BigInt(EXPIRES));
 assert.equal(withG[48],1);
 assert.equal(new PublicKey(withG.subarray(49,81)).equals(guardian),true);
 const noG=c.initialize({owner,agent,beneficiary,mint,perTxMinor:1,dailyMinor:1,lifetimeMinor:1,expiresAt:EXPIRES}).instruction.data;
 assert.equal(noG.length,8+8+32+1);
 assert.equal(noG.readBigUInt64LE(8),0n);
 assert.equal(noG[48],0);
 assert.equal(c.signingSupported,false);
});

test("rejects invalid roles, caps, expiry and amounts like the program",()=>{
 const c=client(),ok={owner,agent,beneficiary,mint,perTxMinor:1,dailyMinor:2,lifetimeMinor:3,expiresAt:EXPIRES};
 assert.throws(()=>c.initialize({...ok,agent:owner}));
 assert.throws(()=>c.initialize({...ok,beneficiary:agent}));
 assert.throws(()=>c.initialize({...ok,guardian:agent}));
 assert.throws(()=>c.initialize({...ok,perTxMinor:5,dailyMinor:4}));
 assert.throws(()=>c.initialize({...ok,perTxMinor:0}));
 assert.throws(()=>c.initialize({...ok,expiresAt:1000}));
 assert.throws(()=>encodePolicy({perTxMinor:1,dailyMinor:1,lifetimeMinor:1,expiresAt:100},200));
 assert.throws(()=>c.deposit({owner,mint,ownerToken:token,amountMinor:0}));
 assert.throws(()=>c.spend({owner,agent,mint,beneficiaryToken:token,amountMinor:1,nonce:-1}));
});

test("program ID is configuration: placeholder, mismatch and off-localnet test ID are refused",()=>{
 assert.equal(PROGRAM,LOCALNET_PROGRAM_ID);
 assert.throws(()=>createTreasuryClient({programId:"11111111111111111111111111111111",verifiedProgramId:"11111111111111111111111111111111",network:"localnet"}));
 assert.throws(()=>createTreasuryClient({programId:PROGRAM,verifiedProgramId:owner.toBase58(),network:"localnet"}));
 assert.throws(()=>createTreasuryClient({programId:PROGRAM,verifiedProgramId:PROGRAM,network:"devnet"}));
 assert.throws(()=>createTreasuryClient({programId:PROGRAM,verifiedProgramId:PROGRAM,network:"testnet"}));
 const other=pk().toBase58();
 assert.equal(createTreasuryClient({programId:other,verifiedProgramId:other,network:"devnet"}).programId.toBase58(),other);
 assert.equal(treasuryConfigFromEnv({}),null);
 assert.deepEqual(treasuryConfigFromEnv({SENDA_TREASURY_NETWORK:"localnet",SENDA_TREASURY_PROGRAM_ID:PROGRAM,SENDA_TREASURY_VERIFIED_PROGRAM_ID:PROGRAM}),
  {network:"localnet",programId:PROGRAM,verifiedProgramId:PROGRAM});
});

test("error codes follow the v2 program (6010 Paused, 6011-6013 new)",()=>{
 assert.equal(treasuryErrorName(6010),"Paused");
 assert.equal(treasuryErrorName(6011),"Unauthorized");
 assert.equal(treasuryErrorName(6012),"MintNotAllowed");
 assert.equal(treasuryErrorName(6013),"InvalidExpiry");
 assert.equal(treasuryErrorName(6014),null);
 assert.equal(Object.keys(TREASURY_ERRORS).length,14);
});

test("decodes a v2 Treasury account, with and without a guardian",()=>{
 const disc=createHash("sha256").update("account:Treasury").digest().subarray(0,8);
 assert.deepEqual([...disc],IDL.accounts.find(a=>a.name==="Treasury").discriminator);
 const u64=v=>{const b=Buffer.alloc(8);b.writeBigUInt64LE(BigInt(v));return b;};
 const i64=v=>{const b=Buffer.alloc(8);b.writeBigInt64LE(BigInt(v));return b;};
 const body=g=>Buffer.concat([disc,Buffer.from([2,254]),u64(7),owner.toBuffer(),mint.toBuffer(),beneficiary.toBuffer(),agent.toBuffer(),
  g?Buffer.concat([Buffer.from([1]),g.toBuffer()]):Buffer.from([0]),
  u64(10),u64(20),u64(30),u64(4),u64(5),i64(1700000000),i64(EXPIRES),u64(2),Buffer.from([0,1])]);
 const t=decodeTreasury(body(guardian));
 assert.equal(t.seedId,7n);assert.equal(t.bump,254);
 assert.equal(t.agent.equals(agent),true);assert.equal(t.guardian.equals(guardian),true);
 assert.equal(t.perTxCap,10n);assert.equal(t.lifetimeCap,30n);assert.equal(t.nextNonce,2n);
 assert.equal(t.revoked,false);assert.equal(t.paused,true);
 const n=decodeTreasury(Buffer.concat([body(null),Buffer.alloc(32)]));// account space is sized for Some(guardian)
 assert.equal(n.guardian,null);assert.equal(n.expiresAt,BigInt(EXPIRES));assert.equal(n.paused,true);
 const v1=body(null);v1[8]=1;
 assert.throws(()=>decodeTreasury(v1),/layout version/);
 assert.throws(()=>decodeTreasury(Buffer.alloc(200)),/Not a Treasury/);
});
